INSERT INTO `movies` VALUES (1,'Джентльмени','Гай Річі',2019,7.8,'poster_69f44fdbd6b567.31953046.jpg','Gentlemen.jpg',1,'Американський бізнесмен Міккі Пірсон перебрався жити до Англії, де фактично став монополістом на ринку канабісу. Оцінивши свою справу в 400 мільйонів доларів, він вирішив продати наркотичну імперію і назавжди піти з нелегального бізнесу. Пропозиція зацікавила його ділових партнерів з Оклахоми, проте вони взяли час на роздуми. Паралельно з цим місцевий наркобарон, не зумівши укласти з Міккі угоду, викрадає його дружину Розалінду з метою шантажу, чим розв\'язує повномасштабну війну за вплив в регіоні ...',1,NULL,NULL),(2,'Ножі наголо','Раян Джонсон',2018,7.9,'poster_69f45080739846.41381145.jpg','Knives_Out.jpg',1,'Здавалося б, сюжет детектива «Ножі наголо» не відрізняється особливою новизною: в день 85-річчя патріарха великої родини, а за сумісництвом багатія і автора детективних романів Харлана Тромбрі, знаходять мертвим з ножем у грудях. Він зібрав свою велику сім\'ю, яка роздирається сварками в своєму маєтку, щоб всіх помирити, але сталося все зовсім не так, як хотів старий. До розслідування підключається поліція, але також і приватний детектив Бенуа Блан в блискучому виконанні цієї ролі актором Деніелом Крейгом ...\r\nІ ось тут-то і починаються цікаві речі, оскільки і сам детектив досить незвичайний, і підозрює він всіх - від служниці з Латинської Америки до дивовижного онука-активіста, від старшого сина, який займався бізнесом з продажу авторських прав батька і постійно з ним сперечався, до навіть онуки, учениці коледжу. І все це пройняте дуже своєрідним гумором, який характерний для фільмів режисера Раяна Джонсона. Так що детектив цей незвичайний, і пошуки вбивці обов\'язково доставлять задоволення глядачам.',0,NULL,NULL),(3,'Джанґо вільний','Квентін Тарантіно',2012,8.4,'poster_69f45cb323bc53.48196352.jpg','Django.jpg',1,'Фільм «Джанґо вільний» (2012) - це динамічний вестерн про ексцентричного і чарівного мисливця за головами на прізвисько «Дантист». Насправді його звуть доктор Кінг Шульц, але набагато більший страх на злочинців навіває саме його прізвисько. Головний герой - неперевершений стрілець і полює тільки на найнебезпечніших і жорстоких бандитів. Робота не проста і ризикована, а тому головному герою потрібен хороший і надійний помічник. Бажано, щоб це була людина з залізними нервами, сталевими м\'язами і вільним графіком роботи. Раб на ім\'я Джанґо прекрасно підходить за всіма критеріями. Головний герой допомагає йому втекти від работоргівців і пропонує вигідну угоду. Що ж залишається робити рабу утікачеві, особливо, якщо наступною мішенню доктора Шульца стануть викрадачі дружини Джанґо? Тепер чорношкірий помічник і Дантист пов\'язані навіть міцніше, ніж варто було б. Доктор Кінг Шульц обіцяє, що допоможе своєму новому підлеглому знайти і врятувати дружину, а поки раб буде слідувати за своїм господарем по п\'ятах. Чи зможуть головні герої домогтися поставлених цілей і чи можна довіряти самому ексцентричному і непередбачуваному мисливцеві за головами на всьому Дикому Заході?',0,NULL,NULL),(4,'Безславні виродки','Квентін Тарантіно',2009,9.0,'poster_69f45d26191fe9.33236420.png','Inglourious_Basterds.png',1,'Одне з найбільш спірних творінь неповторного Квентіна Тарантіно - «Безславні виродки» (Inglorious basterds). Фільм знятий в жанрі історичної драми, але під час перегляду стає ясно, що це, скоріше, альтернативний варіант історії, яку Тарантіно пропустив через призму власного бачення з доброю часткою іронії і специфічного гумору. Перше, що потрібно сказати, описуючи цей фільм: він ні на секунду не дасть вам занудьгувати! Своєрідна атмосфера і музика не змусить вас нудьгувати. Гармонійний розвиток сюжету, бездоганна операторська робота і, звичайно ж, актори! Всі, хто хоч раз дивився це кіно - запам\'ятали Крістофера Вальца в ролі головного лиходія - Ганса Ланда, за яку він отримав Оскар! Фільм - незвичайний, як і більшість творінь Тарантіно.',1,NULL,NULL),(5,'Шерлок Холмс','Гай Річі',2009,7.2,'poster_69f45db9daf1b7.52696392.jpg','Sherlock.jpg',0,'Лондон, 1890 рік. У місті скоєно п\'ять ритуальних вбивств, і ось-ось повинно статися ще одне. Але вправному детективу Шерлоку Холмсу і його вірному другові і помічнику доктору Ватсону (ветерану війни) вдається запобігти злочину, і зловити вбивцю, який відомий як Блеквуд. Його засуджують до смертної кари через повішення. Однак через кілька днів, після виконання вироку, Холмсу повідомляють, що лорд воскрес із мертвих. Місто охоплює паніка. Тепер детективу і його напарнику треба буде докласти чимало зусиль, щоб з\'ясувати обставини воскресіння Блеквуда, і знайти самого злочинця.',0,NULL,NULL),(6,'Великий куш','Гай Річі',2000,8.2,NULL,NULL,1,'Великі гроші можна вважати синонімом великих проблем. Це правило цілком співвідноситься і з великими дорогоцінними каменями. А діамант, який довірили перевозити незграбі Френку - дуже великий.\r\n\r\nНа жаль Френка, про його вантаж дізналися сторонні особи, що не проти отримати камінь у свої руки. А у кур\'єра проблема з азартними іграми, що робить Френка легкою здобиччю.\r\n\r\nАле камінь цей, по всій видимості, має негативну ауру, тому що притягує до себе людей. Компанія мисливців за коштовністю зростає пропорційно часу, який пройшов з моменту пропажі. І все більше людей виявляють себе втягнутими в цю божевільну гонку, нагородою в якій для багатьох може стати смерть.\r\n\r\nАле, незважаючи на ризик, в цій боротьбі беруть участь всі: круті кримінальні боси і останні шістки. Ось тільки кому дістанеться головний приз?',0,NULL,NULL),(7,'Кримінальне чтиво','Квентін Тарантіно',1994,9.1,'poster_69f45f463474c8.36171181.jpg','Pulp_Fiction.jpg',1,'\"Кримінальне чтиво\" - американська комедія, яка вийшла на екрани в 1994 році, написана і знята режисером Квентіном Тарантіно з історії Тарантіно та Роджера Аварі. Репрезентуючись у досить цікавому стилі, Кримінальне чтиво об\'єднує перехресні сюжетні лінії Лос-Анджелеських, бандитів, злочинців, кримінальних спільнот, та таємничий портфель. Назва фільму відноситься до злочинних романів, популярних у середині 20-го століття, відомих своїми графічними насильствами та проникливим діалогом.',0,NULL,NULL),(8,'Мерзенна вісімка','Квентін Тарантіно',2015,7.8,'poster_69f462142320b1.11012980.jpg','Hateful_Eight.jpg',1,'Фільм «Мерзенна вісімка» - психологічний вестерн, сповнений гостросюжетною кінокласикою про влучних стрільців - мисливців за головами, кривавими сутичками, обманом й зрадництвом.\r\n\r\nВайомінг після Громадянської війни. Джон «Вішатель» Рут, що промишляє затриманням злочинців-втікачів, направляється в Ред Рок з багатою здобиччю, бандиткою Дейзі Домерга. У містечку злочинницю чекає вирок і шибениця, а її щасливого переслідувача - десять тисяч доларів обіцяного гонорару. По дорозі в диліжанс Вішателя підсаджуються двоє - темношкірий мисливець за головами, найманець «Маркіз» Уоррен, і колишній конфедерат Кріс Меннікс, який назвався шерифом.\r\n\r\nЩойно почата сніжна буря змушує випадкових попутників сховатися в галантерейній крамниці на перевалі. Тут вже влаштувалася інша четвірка: Ковбой, Мексиканець, Відставний генерал Конфедерації і Висельник - місцевий злочинець-коротун. Незабаром один з «законників», який супроводжує Дейзі, починає небезпідставно підозрювати - серед постояльців закладу зачаївся спільник кривавої отаманші.',1,NULL,NULL),(9,'Карти, гроші і два стволи','Гай Річі',1998,8.2,'poster_69f462cfaef299.32435421.png','Lock, Stock_Two Smoking Barrels.png',0,'Четвірка хлопців мріє про великі заробітки, та так, щоб не довелося при цьому докладати надмірних зусиль. А досягти цього можна лише нечесним шляхом. І кожен з них заробляє так, як може.\r\nЕд, наприклад, професійний гравець, у нього справжній талант і програє він дуже рідко. Бекон і Том зайняті різними незаконними справами, і намагаються при цьому не переходити межі, за якою лежать «серйозні» злочини. «Мило» - не поділяє їх поглядів, але теж не проти отримати швидкий прибуток.\r\nІ вихід друзям бачиться в «великій грі», яку влаштовує місцевий кримінальний король Гаррі Топор. Тут високі ставки, які в разі перемоги обернуться багатством.\r\nАле Гаррі не був би настільки впливовий і багатий, якби звик програвати. Чи не сталося такого і сьогодні, а друзям тепер потрібно терміново шукати гроші, тому що борг Сокири - все одно, що вирок. І якщо не віддати його вчасно - життя перетвориться на пекло, яке, втім, триватиме недовго.',0,NULL,NULL),(10,'Одного разу в Голлівуді','Квентін Тарантіно',2019,7.6,'poster_69f4633a84be58.68654811.jpg','once_upon_a_time_..._in_hollywood.jpg',1,'Одні з найбільш очікуваних подій в світі кіно - це завжди фільми Квентіна Тарантіно, і ось метр трилера і кривавих історій представляє свою дев\'яту роботу в кіно під назвою «Одного разу ... в Голлівуді». Дія відбувається влітку 1969, героями фільму стали колишня зірка вестернів Рік Далтон у виконанні ролі Леонардо Ді Капріо, а також його багаторічний дублер Кліф Бут, якого зіграв Бред Пітт. Напружений сюжет кінокартини розгортається навколо кривавих дій серійного вбивці Чарльза Менсона і його секти ...\r\nСюжет цей заснований на реальних подіях, адже тоді була убита актриса Шарон Тейт, і зроблено це було руками членів даної кривавої секти. Але ці події стали лише поштовхом для «фірмової» кінооповіді Тарантіно, яка невловимо нагадує його найперший фільм «Кримінальне чтиво». Так що дивитися те, що розгортається на екрані, глядачеві дуже цікаво, напружено, криваво і досить похмуро. Але такий Квентін Тарантіно в кіно, і його творчість продовжує зачаровувати ...',0,NULL,NULL),(11,'Початок','Крістофер Нолан',2010,8.8,'poster_69f463e852e5a5.33152295.jpg','Inception.jpg',0,'Ми звикли, що в нашому розумінні злодій - це людина здатна вкрасти якісь цінності або гроші. Сюжет фантастичного бойовика «Початок» розповідає про злодіїв здатних вкрасти ідею прямо у людини з підсвідомості. Одним з таких є головний герой фільму Домінік Кобб. Після того як його дружина померла, він змушений ховатися, і не може навіть повернутися в країну, щоб побачити дітей. Якось раз Кобб отримує дуже неординарне замовлення: йому потрібно не вкрасти, а навпаки впровадити нову ідею в підсвідомість людини. Домініку не надто хотітися братися за цю справу, але замовник в обмін пропонує можливість повернутися додому. Заручившись підтримкою професіоналів цієї справи, Кобб починає розробляти план як все провернути. Все потрібно дуже добре продумати, адже злодіям доведеться відтворити багатошарову реальність в підсвідомості об\'єкта, в результаті чого межі можуть почати стиратися.',1,NULL,NULL),(12,'Інтерстеллар','Крістофер Нолан',2014,9.5,'poster_69f465a90c2d60.74975441.jpg','Interstellar.jpg',1,'В недалекому майбутньому техногенній людській цивілізації прийшов кінець. Землю вразили посухи, які занапастили більшу частину врожаїв. Залишки зернових пожерли бактерії, піщані бурі знищили родючий шар ґрунту. Держави зникли, людство деградувало до сільських комун, розкиданих по Землі - але навіть їх ледь могла прогодувати висохла планета.\r\nФермером довелося стати і головному герою фільму «Інтерстеллар» Куперу. Колишній пілот-випробувач НАСА займався сільським господарством разом з тестем, сином і дочкою. Одного разу Купер зауважив якусь особливість: ферму покривали невідомі радіохвилі. Відшукавши їх джерело, Купер виявив секретну лабораторію НАСА. Там він зустрів професора Амелію Бранд.\r\nПрофесор розповіла Куперу про теорію червоточини, в якій криється порятунок людства. Одна з червоточин знаходиться на орбіті Сатурна і, можливо, веде до світів, придатних для життя. Група Бранд уже побудувала Інтерстеллар - корабель для польоту до Сатурна. Купер стає пілотом експериментального корабля.',1,NULL,NULL),(13,'Матриця','Лана Вачовскі, Ліллі Вачовскі',1999,8.5,'poster_69f4683ca4cf77.35925264.jpg','matrix.jpg',0,'Томас Андерсон - звичайний хлопець, він обіймає посаду програміста в одній великій компанії і чесно виконує свою роль гвинтика в розгалуженій системі. А вечорами він стає іншим - хакером на ім\'я Нео. А відбувається це тому, що Томас незадоволений життям. Ні, не конкретно своїм, а життям взагалі, самим процесом, всесвітом. Думки про те, що все на світі - неправильне, не таке, яким йому належить бути, свердлить його свідомість. А ще Нео сняться незвичайні, тривожні сни, а тому він намагається зовсім не спати, і ще він думає, що потроху позбавляється розуму.\r\n\r\nВідповісти на це запитання може лише одна людина: розшукуваний хакер Морфіус, який теж прагне до зустрічі. Тому як з світом дійсно сталася невеличка неприємність: він нереальний. І Нео - той, кому судилося повернути все на свої місця...',0,NULL,NULL),(14,'Сім','Девід Фінчер',1995,8.6,NULL,NULL,1,'У безіменному американському місті детектив, без 5 хвилин пенсіонер, Вільям Сомерсет співпрацює з короткочасним, але ідеалістичним Девідом Міллсом, який нещодавно перевівся до нового відділку, переїхавши до міста з дружиною Трейсі. Міллс знайомить Сомерсета з Трейсі, після чого Сомерсет стає її довіреною особою. Трейсі невдоволена містом і відчуває, що це не місце для виховання дитини. Вона повідомляє Сомерсета, що вагітна і ще не повідомила свого чоловіка. Сомерсет симпатизує їй, маючи подібну ситуацію з його колишньою дівчиною багато років тому, і порадив їй сказати Міллсу. Та не все так однозначно, і в місті зявляється вбивця, який карає жертву за певні смертні гріхи. У Біблії описано сім таких гріхів, і зупинити страшний ланцюг вбивств під силу тільки ветерану Нью-йоркської поліції і його енергійному молодому напарнику.',0,NULL,NULL),(15,'Острів проклятих','Мартін Скорсезе',2010,8.9,'poster_69f469ce704cd1.83695445.jpg','Shutter_Island.jpg',1,'Фільм «Острів проклятих» - психологічний ретро-трилер, знятий за романом письменника і кіносценариста Денніса Ліхейна.\r\n\r\n1954 рік. Два бостонських федеральних маршала - досвідчений Тедді Деніелс і нещодавно переведений з Сіетла Чак Аулі - пливуть на острів Шаттер (Острів проклятих). Там знаходиться психлікарня, яка добре охороняється а порядками нагадує в\'язницю, куди поміщені божевільні злочинці. Незважаючи на охорону, замки і справну сигналізацію з режимної лікарні примудрилася втекти особливо небезпечна божевільна - Рейчел Соландо, яка в божевіллі втопила своїх дітей.\r\n\r\nНа ділі для Деніелса це відрядження - лише привід відвідати каземати для божевільних: на острові міститься піроман Ендрю Леддіс, винуватець загибелі дружини маршала. Знайти його і утікачку Рейчел - ось завдання для Деніелса, проте розслідування чиновників наштовхується на опір двох завідуючих лікарнею і всього медперсоналу. У їхніх діях змученому головним болем федеральному маршалу починає бачитися якась змова, яка заважає розпочатому розслідуванню.',1,NULL,NULL),(16,'Зодіак','Девід Фінчер',2007,7.7,NULL,NULL,1,'Фільм «Зодіак» - це екранізація однойменної художньої книги Роберта Грейсміта, заснованої на матеріалах реального поліцейського розслідування, що тривало дванадцять років.\r\n\r\nЛипень, кінець 1960-х. У парковій зоні поблизу Сан-Франциско хтось невідомий розстрілює з пістолета закохану парочку, яка розважалася в автомобілі. Десять пострілів, зроблених в упор, не залишають нещасним шансів вижити, а на ранок редакція видання San Francisco Chronicle отримує цікавий лист, що містить шифр. Від газети кілер цинічно вимагає помістити його послання на першій шпальті, в разі відмови погрожуючи поповнити список убитих дюжиною нових імен.\r\n\r\nЗа розслідування справи, яка розтривожила Каліфорнію, беруться троє: детектив Тоскі, азартний репортер кримінальної хроніки Евері і схиблений на криптограмах молодий карикатурист Роберт Грейсміт. Незабаром з\'ясовується: у зашифрованому листі маніяк повідомив, що «вбивати людей - це весело» і побажав, щоб в подальшому його називали «Зодіак». Вийти на слід божевільного злочинця такі одкровення не надто допомагають ...',0,NULL,NULL),(17,'Темний Лицар','Крістофер Нолан',2008,8.9,'poster_69f470daa7c633.42094246.jpg','betman.jpg',0,'Черговий фільм, що розповідає про великого і непереможного героя, що приховує обличчя під маскою летючої миші.\r\n\r\nБетмен продовжує свою війну зі злочинним світом Готема. І в цьому великому очищенні міста від антигромадських типів у нього є помічники: Джим Гордон і Харві Дент, які прагнуть надати йому всю можливу підтримку.\r\n\r\nАле, незважаючи на перемоги, ситуація в місті чомусь не поліпшується. Люди з острахом залишають такі безпечні стіни рідних домівок, і ніхто заздалегідь не знає, коли, де і, що найголовніше, кого наздожене наступний удар. Це відбувається тому, що у героя з\'явився новий ворог. розумний, хитрий, геніальний злочинець на ім\'я Джокер.\r\n\r\nПочинається протистояння, результат якого визначить долю міста. Чи зуміє всемогутній Бетмен перемогти, постійно перебуваючи в ситуації, коли ворог завжди випереджає його?\r\n\r\nОпис переозвучення: Джокер «Де ти був 8 років?» Це 45 хвилин переозвучки фільму \"Темний Лицар\" Крістофера Нолана 2008 року - яка намагається відповісти на найдибільніше питання в історії людства \"Где ты был 8 лет?\" Тонка адаптація змусить вас подивитися на давно відомий сюжет під новим кутом, а вже знайомі герої перевернуться з ніг на голову бо не дарма в цій версії назва фільму це саме Джокер… Обережно, оскільки другорядні персонажі орки то 25% переозвучки озвучені московитьскою мовою і з матюками, а інші 75% озвучені мовою фактів.',1,NULL,NULL),(18,'Бійцівський клуб','Девід Фінчер',1999,8.8,'poster_69f473d3770c42.60437514.jpg','Fight_Club.jpg',1,'При спільному виробництві США та Німеччини фільм вийшов в прокат в 1999 році. Фільм досить жорстокий, в ньому присутні психологічні моменти, сірого реалізму і жорстоких сутичок в рингу. Екранізація вийшла вкрай хорошою, і мабуть, не розчарувала шанувальників літературного твору, адже фільм знімався за однойменною книгою Чака Паланіка. Всім глядачам сподобаються ефектні і динамічні події. А несподівана розв\'язка, яку неможливо передбачити повалить в шок.\r\nСюжет фільму «Бійцівський клуб»: оповідачем історії є типовий яппі. Йому тридцять і він найманий робітник. Так само він мучиться від безсоння, і не може визначити де сон, а де дійсність. Замість ліків лікар йому пропонує зайнятися спортом і періодично відвідувати групу хворих на рак яєчок. Відвідування даної групи має довести оповідачеві, що таке справжня мука, і щоб він зрозумів що його безсоння в порівнянні з раком сущі дрібниці. Так само наш оповідач мріє про переломний момент, який переверне все його життя. Одного разу в барі він знайомитися з Тайлером Дьорденом, торговцем милом, який володіє значним даром ...\r\nВи можете дивитися онлайн фільм «Бійцівський клуб» на нашому кінопорталі в хорошій HD якості абсолютно безкоштовно і без реєстрації. Насолоджуйтесь переглядом!',0,NULL,NULL),(19,'Втеча з Шоушенка','Френк Дарабонт',1994,9.8,'poster_69f474321c45a7.16784741.jpg','Shawshank_Redemption.jpg',0,'В основу культової драми «Втеча з Шоушенка» лягла повість Стівена Кінга «Ріта Хейворт з Шоушенка». Дії фільму розгортаються в кінці 50-х років минулого століття. Молодого фінансиста Енді Дюфрейна за подвійне вбивство засуджують до довічного ув\'язнення, але він категорично заперечує свою причетність до злочину. Свій термін Енді відправляється відбувати в одну з найвідоміших в\'язниць - Шоушенк, з якої ще нікому не вдавалося втекти. У в\'язниці хлопець стикається з суворими реаліями тюремного світу, світу, де немає місця жалю, а навколо тільки жорстокість. Енді неодноразово ставав жертвою сексуальних домагань, але він пручається до останнього. Незабаром тюремне життя Дюфрейна трохи налагоджується, і він навіть знаходить собі друга, яким став чорношкірий ув\'язнений Ред...Один з небагатьох фільмів - \"Втеча з Шоушенка\" - заслуговує перегляду та осмислення',1,NULL,NULL),(20,'Хрещений батько','Френсіс Форд Коппола',1972,9.4,'poster_69f47483f12da5.13329361.jpg','Godfather.jpg',1,'Гангстерська сага «Хрещений батько» є одним з найкращих фільмів усіх часів. Цій картині наслідували, її цитували, нею захоплювалися частіше, ніж будь-яким іншим фільмом. Геніальна режисура Копполи, чудовий сюжет, чудово зіграні Марлоном Брандо і Аль Пачіно батько і син Корлеоне, неперевершена музика, - все це зробило «Хрещеного батька» воістину незабутнім.\r\nФільм розповідає про мафіозний клан Корлеоне, главою якого є Дон Віто. Вся рідня займається сімейним «бізнесом», крім молодшого сина Майкла, який щойно повернувся з армії. Він не бажає бути мафіозі, але доля не залишає йому вибору: старший брат загинув, на батька скоєно замах. Майкл Корлеоне під важким тягарем відповідальності встає на чолі сім\'ї. Ми спостерігаємо за моторошними метаморфозами, що відбуваються з Майклом, вершиною яких стає його моральний крах.',1,NULL,NULL),(21,'Славні хлопці / Круті хлопці','Мартін Скорсезе',1990,8.7,'poster_69f474e469f2b8.86891035.jpg','Goodfellas.jpg',1,'Вічний кінофільм про нелегку і суперечливу долю гангстерів, які з дитинства вибрали собі неправильний шлях і не готові просити спокути. \"Славні хлопці\" - це посібник для справжніх злодіїв, які хочуть пов\'язати своє життя з Мафією. Наркотики, грабіж, крадіжка і махінації - все це не чужі поняття для Генрі Хілла, Джимі Конвея і Томмі Де Віто.\r\n\r\nІсторія починається з біографії юного Генрі Хілла, який з дитинства уявляв себе виключно в ролі крутого, злісного гангстера. Його головними прикладами служили бандити з детективів і кінофільмів. Саме тому нічого іншого як власного майбутнього гангстером, Генрі уявити навіть і не міг. Влаштувавшись в бар одного великого діяча Мафії на ім\'я Пол, Хілл знайомиться зі своїми майбутніми напарниками. Руйнуючи все на своєму шляху, вбиваючи без причини і крадучи без розбору, вони досягають великих висот в бандитському світі.\r\n\r\nВсе б так і тривало, проте Генрі доводиться постраждати від рук своїх же вірних друзів. Після чого він приймає досить-таки необачне рішення стосовно Джимі і Томмі ...',0,NULL,NULL),(22,'Шалений Макс: Дорога гніву','Джордж Міллер',2015,8.0,'poster_69f476114e8525.84109686.jpg','Mad_Max.jpg',0,'Колись давно в минулому житті Макс Рокотанскі був службовцем Основного Силового Патруля, мав люблячу дружину і дитину і затишний будинок, але позбувся всього цього за примхою банди злочинців, які вбили його родину. Після смерті дружини і сина для Макса найголовнішою метою стала помста. Саме вона не дозволила йому зійти з розуму від горя. Але після того, як всі винуватці були знайдені і знищені, життя перестало цікавити спустошеного чоловіка. Його абсолютно не хвилює той факт, що почалася енергетична криза та через що колишній світ канув у минуле, а світова війна знищила колись квітучу землю, перетворивши її на мляву пустелю. Тепер влада в світі належить тому, хто володіє паливом, запасами води та їжі. По всьому світі з\'являється безліч банд, кожна з яких пишається своєю жорстокістю і силою. Мимоволі Максу доведеться вчитися жити в цьому новому жорстокому світі і обзаводитися новими соратниками і друзями ...',0,NULL,NULL),(23,'Гладіатор','Рідлі Скотт',2000,8.5,'poster_69f476e394adf1.97053460.jpg','Gladiator.jpg',1,'Древній Рим. Час честі і гордості. Час великої експансії, коли залізна хода незламних легіонів трясла основи світу, і царства одне за іншим опускалися перед Римом на коліна. І Рим не мав більш талановитого і, як ніхто інший, відданого справі полководця, ніж Максимус.\r\n\r\nАле все змінюється і благородство не властиве всім і кожному. Максимус був немов сином для старого імператора, який мав на полководця великі плани. Але імператор помер, а його справжній син не бажає суперництва. А це означає, що Максимус повинен зникнути. Померти, доставивши при цьому задоволення натовпі, борючись на арені.\r\n\r\nАле Максимус не може дозволити собі померти до того моменту, як його помста не буде завершена.',0,NULL,NULL),(24,'Чужий','Рідлі Скотт',1979,8.0,NULL,NULL,0,'Оглушливі події фільму «Чужий» відбуваються в далекому майбутньому, коли інопланетні відрядження перетворюються в повсякденну реальність. Буксир «Ностромо», що борознить космічні простори, повертається на Землю з вантажем руди, а його екіпаж мирно перебуває в анабіозі. Сон астронавтів переривається бортовим комп\'ютером, який прийняв сигнал лиха з малодослідженої планети.\r\n\r\nГрупа космольтчиків відправляється на розвідку і виявляє інопланетний корабель, який зазнав катастрофи, всередині якого - труп пілота-інопланетянина. Опинившись в зорельоті, рятувальники втрачають зв\'язок з «Ностромо», тому не можуть дізнатися, що сигнал про допомогу виявився попередженням про небезпеку.\r\n\r\nУ трюмах корабля астронавти знаходять дивні кокони, один з яких від дотику розкривається. Моторошний павукоподібний монстр вистрибує з нього, пропалює скафандр помічника капітана і присмоктується до лиця бідолахи. Кидати товариша не в правилах капітана, і, порушуючи інструкцію, ще живого пілота разом з істотою проносять на буксир. Це велика помилка: інопланетна тварюка плюється кислотою, швидко зростає і жадає вбивати ...',0,NULL,NULL),(25,'Щось','Джон Карпентер',1982,7.5,'poster_69f4790d8faa53.51483042.jpg','Thing.jpg',0,'Фільм «Щось» - культовий американський фільм жахів, з науковим підґрунтям.\r\nПолярники з бази США спостерігають дивну картину: їх норвезькі колеги переслідують їздову собаку на вертольоті, намагаючись всіма способами вбити тварину.\r\nВ ході колотнечі один з американців отримує поранення, а непрохані гості гинуть. Собаку замикають в вольєрі. А пілот і лікар відправляються на норвезьку станцію, щоб з\'ясувати причини того, що сталося.\r\nВони виявляють там розруху, знаходять тіло дослідника, який застрелився і спалені останки, схожі на людські. Крім того їм на очі потрапляє брила льоду, з якої щось було вилучено. Для подальшого вивчення полярники переносять зібрані матеріали до себе на базу.\r\nДосить швидко команда розуміє, що зіткнулася з позаземною формою життя, звільненою з крижаної пастки. Вона може підпорядковувати собі тіло жертви та є вельми агресивною. Зараза починає розповзатися, погрожуючи перекинутися на материк. Можливо, для порятунку життів мільйонів людей полярникам доведеться пожертвувати своїми ...',0,NULL,NULL),(26,'Пастка/Геть','Джордан Піл',2017,7.6,'poster_69f48088965b98.66222185.jpg','get_out.jpg',0,'Успішний і досить заможний афроамериканець на ім\'я Кріс, - головний герой фільму \"Пастка\". Молодий хлопець закоханий в світлошкіру дівчину Роуз, і відчуває таке ж відношення і до себе. Цей прекрасний роман триває не довго, хлопець незабаром робить своїй коханій пропозицію. І дівчина відразу ж дає свою згоду. Буквально через деякий час Роуз запрошує свого коханого в свій родовий маєток для знайомства зі своїми батьками. Батьки дівчини живуть в штаті Нью-Йорку в невеликому містечку.\r\n\r\nАле все починається не дуже добре, вже по дорозі з парою відбуваються невеликі неприємності, і по приїзду до батьків, Кріс відчуває до себе не зовсім щире ставлення. Прогулюючись зі своєю нареченою по місту, хлопець помічає, що основна маса населення - білі. А негри тут працюють в якості слуг. Крісу здається, що він потрапив в інший вік, коли було расове обмеження. Але чим довше він тут живе, тим більше його шокує життя містечка. Він дізнається, що багато чорношкірих, які прибувають в місто, просто безслідно зникають. Подивившись картину, можна дізнатися, чи вплинуть на відносини молодих всі ці відкриття? І чи зможе виїхати до себе хлопець живим і неушкодженим?',0,NULL,NULL),(27,'Король Лев','Роджер Аллерс',1994,8.5,'poster_69f481308c47b7.02841519.jpg','lion_king.jpg',1,'У лева на ім\'я Муфаса, короля неосяжної савани, з левицею Сарабі, люблячої його дружиною, з\'являється на світ левеня - спадкоємець титулу батька, якому дають ім\'я - Сімба. У короля Муфаси є брат на ім\'я Шрам, який упевнений, що трон неодмінно повинен стати його, а що з\'явився маленький спадкоємець, природно, заважає здійсненню цього бажання, тому він впевнено вирішує покінчити з Сімба. Відправивши його на слоняче кладовищі, Шрам підсилає гієн, але Муфаса допомагає Сімбі і рятує його, не підозрюючи про підступність брата. Одного разу батько гине, рятуючи Симбу, і маленький спадкоємець, переконаний, що винен у смерті свого батька, покидає свої землі.',0,NULL,NULL),(28,'Людина-павук: Навколо всесвіту','Bob Persichetti, Пітер Ремсі, Родні Ротман',2017,8.0,'poster_69f481939ea378.64071433.jpg','Spider-man_cartoon.jpg',0,'Мультфільм «Людина-павук: Навколо всесвіту» - нова і абсолютно унікальна картина, що показує головного героя Майлза Моралеза, який є супергероєм, та проживає у великому і шумному Нью-Йорку. Він носить костюм Людини-павука і має безліч незвичайних суперздатностей. Герой має неймовірний зір, може дертися по самих стрімких стінах, випускає павутину і, звичайно, вершить добро. Одночасно з цим, він є звичайним підлітком, який відвідує школу і відчайдушно приховує свій секрет, адже Майлз боїться бути незрозумілим і відкинутим.\r\nЗберігати цю таємницю дуже складно, адже лиходії не дрімають, і підлітку потрібно надягати свій костюм і виходити на охорону порядку і спокою свого містечка. Але, виявляється, Майлз не єдиний, хто одягає свій геройський костюм Людини-павука, незабаром юнака чекає знайомство з іншими хлопцями, такими ж унікальними, як і він сам. Ця зустріч відбудеться, як ніколи доречно, адже на місто насувається чергове зло, якому потрібно перешкодити, а протистояти йому краще разом, дружною командою.',0,NULL,NULL),(29,'ВОЛЛ-І','Ендрю Стентон',2008,9.0,'poster_69f4820611ac66.94568804.jpg','WALL_E.jpg',1,'Дії фантастичного мультфільму від студії Walt Disney Pictures «ВОЛЛ-І» розгортаються в далекому майбутньому, коли Земля стала непридатна для життя і люди були змушені її залишити. Єдиний, хто залишився на планеті - це робот ВОЛЛ-І. День у день він займається виконанням закладеної в нього програми - збирає і утилізує сміття. За довгі роки в роботі відбувається якийсь збій, що сприяє розвиток в ньому невластивих механізму якостей. Одного разу серед гір сміття ВОЛЛ-І знаходить справжній живий паросток, за яким починає доглядати. Незабаром на Землю прилітає робот-розвідник Єва, посланий людьми дізнатися, як йдуть справи на рідній планеті. Занурений в повну самотність ВОЛЛ-І закохується в Єву, і намагається всіляко за нею доглядати. Але вона повністю зосереджена на закладеній в неї програмі, і коли ВОЛЛ-І показує їй рослину, вона забирає її і повертається на «Аксіому». Аби більше залишатися на самоті, ВОЛЛ-І відправляється за коханою, в надії знову її побачити.\r\n\r\nПаралельно подіям, які проходять на Аксіомі, просинається ще один робот БЕРН-І, який попадає в справжню подорож виконуючи запрограмоване завдання.',1,NULL,NULL),(30,'20 Днів у Маріуполі','Мстислав Чернов',2023,9.9,'poster_69f482e96d02b7.08119084.png','Mariupol.png',1,'Група українських журналістів документує жахливі реалії війни, опинившись у прибережному місті Маріуполь після вторгнення російських військ на початку 2022 року.',1,NULL,NULL),(31,'Довбуш','Олесь Санін',2023,8.0,'poster_69f483c1e98646.15249211.jpg','Dovbush.jpg',0,'Події фільму відбуваються в Карпатах на початку XVIII століття. Жорстоке правління польської шляхти змушує гуцулів тікати в гори. Двоє братів, Олекса та Іван Довбуші, опиняються поза законом і стають опришками. У пошуках помсти панам брати стають ворогами один одному. Один прагне грошей, другий — справедливості. Гуцули починають повстання, яке очолює Олекса. Шляхта робить усе можливе, аби знищити Довбуша.',0,NULL,NULL),(32,'Тіні забутих предків','Сергій Йосипович Параджанов',1965,9.0,'poster_69f4843392e473.13787484.jpg','Shadows.jpg',1,'Головні герої чудової екранізації легендарного творіння українського письменника Михайла Коцюбинського проживають в тихому і маленькому поселенні, де кожен день не надто відрізняється від попереднього. Одні жителі вічно сваряться з сусідами, інші жити не можуть без них. Загалом, типове життя, насичене буденними проблемами. І Марічка з Іваном марять про світле майбутнє, але їх щастя розділене практично нездоланною стіною. \r\nГерої представляють дві ворогуючі споконвіку сім\'ї, так що молоді змушені від усіх приховувати пристрасть і спалахнувшу в серці любов. Ховаючись по кутах і підворіттях, лише короткі миті дозволяють їм пригорнутися губами і доторкнутися до коханого, як вже через секунду необхідно відвернутися і уявити, що ніколи не були знайомі. Так би і тривало все життя, якби в один момент кохана Івана не потонула в річці. \r\nГлядачам розкриється зворушлива історія двох молодих героїв, що не уявляють подальшого життя один без одного. Після втрати дорогої душі весь навколишній світ втрачає барви: негоди стають все більш похмурі, а кожен день - муками. Що ж буде робити Іван зі своїм життям? Чи зможе забути своє кохання?',0,NULL,NULL),(33,'Дюна','Денні Вільньов',2021,8.0,'poster_69f48529a67566.28403635.jpg','Dune.jpg',0,'Дім Атрідів підправляється з рідної планети Калладна на планету Аракіс, що представляє собою пустелю з суворими умовами для виживання і небезпечними істотами, але саме ці володіння дозволяють Аракісу бути наймогутнішим місцем у Всесвіті. На цій планеті видобувають цінний ресурс, званий «меланж». Це найдорожча речовина з усіх існуючих, оскільки вона розкриває особливі здібності людини. Ті, хто володіє пряністю, диктують умови всім мешканцям Всесвіту. Герой фільму «Дюна» є спадкоємцем знаменитого дому. Зараз Пол готується стати повноправним наступником. Він знає, що навколо їх сім\'ї постійно зріють змови з метою позбавити їх могутності. Але хлопець не очікував, що вступити в протистояння і боротьбу за владу йому доведеться так скоро. На нього чекають серйозні і небезпечні випробування, також не раз життю Пола загрожуватиме смертельна небезпека, а потім спадкоємець дізнається страшну таємницю, що зберігає його планета.',0,NULL,NULL),(34,'Той, хто біжить по лезу 2049','Дені Вільньов',2017,8.0,'poster_69f485a9a21af7.68657118.jpg','Blade_runner.jpg',0,'2049 рік, в футуристично-абсурдному майбутньому люди перетворили реплікантів в рабів, яких жорстоко експлуатують, змушують виконувати найскладнішу і ризиковану роботу, а потім знищують. 30 років тому офіцерові Ріку Декарту довелося мати справу з бунтівними роботами, але незабаром він усвідомив, що ці механічні істоти практично не відрізняються від людини - вони еволюціонували в своєму розвитку, стали високоорганізованими «особистостями», навчилися відчувати різні емоції. І такі зміни стали можливі завдяки розвитку технічного прогресу. Суспільство дуже помиляється, коли утискає права кіборгів, які теж гідні жити щасливо. Як відомо, Рік полюбив дівчину-андроїда, це вплинуло на його професійні принципи і повністю змінило ставлення до олюднених кіборгів. Після нього «тим, хто біжить по лезу» стає молодий лос-анджелеський поліцейський Кей, який володіє нетривіальними навичками. Керівництво поставило перед Кеєм ту ж задачу, яку повинен був вирішити його попередник - ловити «поламаних» кіборгів, щоб піддати їх фізичному винищенню. Однак, дізнавшись про одну стару таємницю, що загрожує погубити все людство, Кей переконується в тому, що світ несправедливий до продуктів генної інженерії. У нього накопичилося багато питань, які він збирається поставити Декарту. Скоро Кей виходить на слід колишнього агента космічного підрозділу, і Рік розповідає тому моторошну правду про реплікантів.',0,NULL,NULL),(35,'Паразити','Пон Джун Хо',2019,8.6,'poster_69f4862688eaa6.52602919.jpg','Parasite.jpg',0,'У центрі історії знаходиться бідне сімейство Кім, що складається з безробітного водія Гі-Тека, його дружини Чхун-Сук, сина Гі-У і дочки Гі-Чон. Вони живуть в старій напівпідвальній квартирі і намагаються звести кінці з кінцями, збираючи картонні коробки для піци. Одного разу Гі-У отримує можливість попрацювати репетитором англійської мови для дівчини з багатої сім\'ї Пак. За допомогою підробленого диплома, виготовленого сестрою, хлопець успішно проходить співбесіду і, зачарований розкішним життям цих людей, придумує незвичайний спосіб вирішення фінансових проблем своїх родичів ...',0,NULL,NULL),(36,'Джокер','Тодд Філліпс',2019,8.0,'poster_69f4880e0959e6.72786407.jpg','Joker.jpg',0,'Кінофільм \"Джокер\" - серйозна психологічна драма, яка доведе - Комікси можуть бути дуже серйозними. Історія розповість про звичайного чоловіка Артура Флека, який, як і тисячі інших людей пробує реалізуватися у великому місті. У чоловіка постійні проблеми з роботою, він ходить до психіатра, удома його чекає старенька матір. Навколо героя суцільний негатив і це просто зводить його з розуму. Та у кожного є мрія. У Артура вона є також. Він бажає жартувати і бути стендап коміком. Попри всю важкість свого становища, чоловік бажає веселити публіку.\r\nАле і тут не все пройде так, як він очікував. Події фільму охоплять той відрізок його життя, де все піде не за планом. Чоловіка чекають великі потрясіння, великі зміни і що з цього вийде - побачить кожен глядач переглянувши фільм.\r\nРежисер Тодд Філіпс дав кожному глядачу простір для уяви та роздумів, тому фільм буде потрактований багатьма людьми по різному. Для когось Артур - соціопат, якого зламало суспільство. Для когось - жорстокий убивця. Хто ж він насправді, цей Джокер? Питання завжди залишиться нерозгаданим.\r\nПісля виходу фільму на великі екрани виявилось, що він був вкрай неоднозначним і викликав у глядачів бурю емоцій. Аудиторія поділилась на два фронти: одні розуміли, підтримували та співчували Артуру Флеку. Інші ж засудили джокера і назвали його справжнісінькою хворобою суспільства. Одні сприйняли фільм, як гарну адаптацію, а інші в свою чергу заявили про не канонічність образу. Тому спробуйте переглянути фільм, та скласти своє власне враження від перегляду. Фільм однозначно вартий Вашої уваги!',0,NULL,NULL),(37,'Хороший, поганий, злий','Серджіо Леоне',1966,8.9,'poster_69f48abaaa0d46.04225379.jpg','Good_Bad_Ugly.jpg',1,'Фільм «Хороший, поганий, злий» - суворе кіно в стилі вестерн, до цих пір вважається кращим в своєму жанрі.\r\nПодії у фільмі розгортаються в роки громадянської війни, нахабні, небезпечні авантюристи об\'єднуються з метою знайти заховане золото.\r\nХороший - блондин, у виконанні Клінта Іствуда, харизматичний і милий, стріляє в кожний непотріб, відзначаючи перемоги стаканчиком міцного віскі. Його партнер - Поганий, з ангельськими очима, але абсолютно аморальний і безглуздий тип, якого розшукує поліція. Злий - істеричний і дивний тип, разом, ця різношерста компанія розшукує золото, заховане десь в могилі. Чому вони разом? Справа в тому, що кожен з них знає лише малу частину цілої інформації, з\'єднавши яку вони зможуть дійти до скарбу, якщо до цього не повбивають один одного.\r\nФільм «Хороший, поганий, злий» вийшов на екрани в 1966 році і викликав обурення через сцени насильства і бійок, але сьогодні він є найкращим в плані режисури і займає п\'ятий рядок у списку найкращих фільмів світу всіх часів.',0,NULL,NULL),(38,'Ла Ла Ленд','Дем\'єн Шазелл',2016,8.4,'poster_69f48faedb0f03.96617295.jpg','land.jpg',0,'Нова кінострічка режисера Дем\'єна Шазелла - це мюзикл, мелодрама, комедія і історія любові в одній кінострічці. Лос-Анджелес (Ла-Ла Ленд) - дивовижне місце, фабрика мрій і рай на землі в очах багатьох молодих людей. Саме тут двом головним героям кінокартини судилося зустрітися, знайти і втратити своє щастя. Вона - молода амбіційна актриса, яка мріє стати кінозіркою. Працюючи офіціанткою в кав\'ярні, вона подає каву знаменитим акторам і актрисам, а весь вільний час дівчина ходить на нескінченні кастинги і прослуховування, не залишаючи надію одного разу отримати свою зоряну роль. Він - молодий і талановитий джазовий піаніст, який мріє стати визнаним композитором і відкрити свій джаз-клуб. Однак він змушений заробляти собі на життя, граючи одні і ті ж невигадливі пісеньки в ресторані.\r\nІ ось доля зводить їх разом, змушуючи два серця битися з новою силою. Любов повертає в їх життя все найсвітліше і чисте. І головні герої, одухотворені своїми почуттями, з новими силами кидаються до своїх заповітних мрій. Успіх, нарешті, приходить до обох, і закохані з подивом виявляють, що тернистий шлях до слави і можливості, що відкриваються починають вбивати їх любов ...',0,NULL,NULL),(40,'Врятувати рядового Раяна','Стівен Спілберґ',1998,8.3,'poster_69f4908a575447.89147061.jpg','Saving_Private_Ryan.jpg',0,'Війна - це завжди жахливе видовище: горе, смерть, бойові втрати, загибель друзів і близьких. У матері Джеймса Райана було четверо синів, а тепер залишився тільки один, інші стали черговими жертвами в м\'ясорубці війни. Але Джеймс в бою, в будь-яку хвилину він теж може відправитися на той світ ...\r\n\r\nКомандування вирішило, що мати не повинна втратити всіх, тому Джон Міллер і його загін отримують наказ: «Будь-якою ціною, вони повинні витягти з передової Раяна і живим повернути назад додому». Але наказ цей непросто виконати, тому що Джеймс на далекому фронті, а навколо вороги ... Крім того, солдат постійно переміщається, і спроба знайти когось в метушні постійних боїв перетворюється в самовбивчу затію. Але наказ - є наказ.',0,NULL,NULL),(41,'Форд проти Феррарі','Джеймс Менголд',2019,7.9,'poster_69f4917a89e1e7.27868319.jpg','Ford_vs_Ferrari.jpg',1,'Захоплюючий та цікавий фільм «Ford проти Ferrari» заснований на реальних подіях 1966 року, коли Генрі Форд Другий спочатку намагався купити компанію «Феррарі», а коли це в нього не вийшло, поставив перед своїми працівниками, здавалося б, нездійсненне завдання - перевершити непереможний досі автомобіль «Феррарі» на добовій гонці на витривалість Ле-Ман. І ось якраз про цих людей, які абсолютно фантастичним чином вирішили це завдання, і піде мова в цьому фільмі ...\r\nПерш за все - це конструктор Керролл Шелбі з його колективом молодих інженерів і гонщик Кен Майлс. Якраз запаморочливій ​​історії створення автомобіля Форд GT-40, що став легендою в автомобілебудуванні, і присвячений фільм. Ну, а результат? Хіба могли ці люди поступитися «Феррарі»? Подивіться біографічний фільм, який за своїм драматизмом перевершує вся і всіх, як найшвидший з усіх легендарний «Форд», і все побачите своїми очима ... Ну, а актори Крістіан Бейл і Метт Деймон стали гідними виконавцями головних ролей в даній захоплюючій кінокартині.',0,NULL,NULL),(42,'Сам удома','Кріс Коламбус',1990,8.4,'poster_69f49260d5f713.09249306.png','Home_Alone.png',1,'Фільм «Один вдома» - це весела новорічна історія, яка трапилася з проникливим малюком на ім\'я Кевін Маккалістер. Його численне сімейство не балували молодшого увагою: старші брати знущалися, сестри відверто ігнорували, а батьки були поглинені підготовкою до майбутнього переїзду в Європу. Засмучений і скривджений на всю свою велику рідню Кевін побажав, щоб всі його близькі зникли. Бажання малюка збулося. Батьки настільки захопилися переїздом, що просто забули дитину вдома. Тепер юному даруванню доведеться різко стати самостійним. Ситуація ускладнюється тим, що на багатий будинок Маккалістреров поклали око місцеві грабіжники. Вони впевнені, в своїх силах і вважають, що цей будинок стане для них легкою здобиччю. Здогадавшись про те, що його хочуть пограбувати хитрий малюк вирішує взяти оборону особняка в свої руки. Він розробляє хитромудрий план і заманює злочинців-невдах в саме серце кумедних пасток. Але дорослі виявляються міцними горішками. Тепер дістатися до головного героя - це справа їх честі. Хто ж виявиться розумнішим - два дорослих грабіжника зі стажем або дев\'ятирічна дитина, який один вдома?',0,NULL,NULL),(43,'Зелена книга','Пітер Фарреллі',2018,9.0,'poster_69f492cc54a3b3.82794424.png','Green_Book.jpg',1,'Дія фільму, заснованого на реальних подіях, розгортається в 1962 році. Італо-американець Тоні на прізвисько \"Базіка\" працює викидайлом в одному з престижних нічних клубів Бронкса. Коли заклад закривається на ремонт, Тоні вирішує знайти тимчасову роботу, і незабаром у нього з\'являється пропозиція. Відомий афроамериканський піаніст Дон Ширлі збирається в турне по південних штатах, і йому потрібен хороший водій і людина, здатна вирішити в дорозі будь-яку проблему, в одній особі. Обумовивши всі нюанси і прийшовши до спільної згоди, талановитий музикант і вибивала з Бронкса вирушають в дорогу, взявши з собою \"Зелену Книгу\" - спеціальний путівник, в якому описані всі безпечні для афроамериканців місця.',1,NULL,NULL),(44,'Освідчення','Енн Флетчер',2009,7.6,'poster_69f493ee16a516.58364030.jpg','Proposal.jpg',0,'Фільм «Освідчення» - романтична комедія про серйозність фіктивних відносин. \r\nМаргарет Тейт займає в престижному видавництві високий пост. Вона зосереджена на роботі і не відволікається на проблеми оточуючих або зайве спілкування з ними. Співробітники офісу завмирають при наближенні начальниці, а керівництво повністю влаштовує її результативність. Однак через свою зацикленість на справах Маргарет пропускає кілька повідомлень щодо робочої візи, яка уже от-от закінчиться і з подивом дізнається, що знаходиться на межі депортації в Канаду. Вона поспішно складає історію про швидкий шлюб з асистентом Ендрю Пекстоном. Молода людина погоджується на аферу заради підвищення і публікації одного з рукописів. \r\nЗалишається одна проблема: імміграційний контроль в подібних випадках проводить ретельну перевірку правдивості відносин. Ендрю знає про своє боса все, а ось їй доведеться постаратися, щоб відповісти на питання комісії. \r\nПара відправляється на батьківщину Ендрю, де їх зв\'язок проходить випробування родичами, знайомими і чиновниками, щоб в результаті перерости в справжнє почуття.',0,NULL,NULL),(45,'Парк Юрського періоду','Стівен Спілберґ',1993,8.5,'poster_69f494de547625.05842401.jpg','Jurassic_Park.jpg',0,'Відомий американський вчений створив унікальний парк давно зниклих з лиця Землі динозаврів. Тварини були клоновані з застиглої крапельки крові, в якій збереглися ДНК цих тварин. Парк юрського періоду знаходиться на безлюдному острові, на який і прилітають два головні герої - вчені. Їх завдання - обстежувати і дати оцінку парку ще до його офіційного відкриття для відвідувачів. Всі динозаври знаходяться в спеціальних вольєрах, оточених дротом під електричною напругою. Через збій в системі струм раптово зникає і динозаврам вдається вийти на волю і тепер вони вільно розгулюють по парку. Весь жах ситуації полягає в тому, що разом з нешкідливими травоїдними на свободу вирвалися хижі м\'ясоїдні динозаври.',0,NULL,NULL),(46,'Диявол носить Прада','Девід Франкель',2006,8.2,'poster_69f495665c41f5.72460556.jpg','Devil_Wears_Prada.jpg',0,'Фільм «Диявол носить Prada» - креативна екранізація літературних спогадів Лорен Вайсберг, написаних під враженням нетривалої співпраці з Vogue.\r\n\r\nЮна Енді Сакс, провінційна журналістка з великими амбіціями, скромним досвідом і бажанням публікуватися в «Нью-Йоркському» медіа, отримує роботу в модному глянцевому «Подіумі». Дівчині належить стати асистенткою головного редактора Міранди Прістлі - великої і жахливої ​​законодавиці світу моди, що приводить в священний трепет модельєрів, фотографів і редакторів. Співпрацювати з «Подіумом» мріють всі дівчата, проте Енді Сакс не до душі «модна» робота: емблема D & G для неї звук порожній, почуття стилю незнайоме, а шостий розмір одягу жахливим не здається.\r\n\r\nСвіт гламуру, де нероздільно панує Міранда, намагається переробити героїню. Доручення патронеси - безглузді і нездійсненні - сиплються каменепадом, відносини з бойфрендом безповоротно псуються, а робочий тиждень, ледь розпочавшись, здається вічністю. Але, можливо, ці труднощі - перша ознака вдалої кар\'єри і майбутнього підвищення?',0,NULL,NULL);
